const entrada = $input.first().json;

// O HTTP Request deve devolver o CSV como texto no campo "data".
const csv = entrada.data;

if (typeof csv !== 'string' || !csv.trim()) {
  throw new Error('CSV não encontrado no campo data.');
}

// Divide o conteúdo em linhas
const linhas = csv.trim().split(/\r?\n/);

// Detecta o separador usado no cabeçalho
const separador = linhas[0].includes(';') ? ';' : ',';

// Extrai o nome de cada coluna
const cabecalho = linhas[0]
  .split(separador)
  .map(coluna => coluna.trim().replace(/^"|"$/g, ''));

// Converte cada linha em um objeto JSON
const investimentos = linhas.slice(1)
  .filter(linha => linha.trim())
  .map(linha => {
    const valores = linha.split(separador);

    const investimento = {};

    cabecalho.forEach((coluna, indice) => {
      investimento[coluna] = (valores[indice] ?? '')
        .trim()
        .replace(/^"|"$/g, '');
    });

    return { json: investimento };
  });

return investimentos;

const itens = $input.all().map(item => item.json);

// 1. Localizar os clientes recebidos pelo Webhook
const entradaClientes = itens.find(
  item => Array.isArray(item.body?.clientes)
);

if (!entradaClientes) {
  throw new Error("Lista de clientes não encontrada.");
}

const clientes = entradaClientes.body.clientes;

// 2. Separar os investimentos recebidos do CSV
const investimentos = itens.filter(
  item => !Array.isArray(item.body?.clientes)
);

// 3. Recomendar investimentos conforme o perfil
const recomendacoes = clientes.map(cliente => {

  const perfilCliente = String(cliente.perfil)
    .trim()
    .toLowerCase();

  const investimentosIndicados = investimentos.filter(
    investimento => {

      const perfilInvestimento = String(
        investimento.perfil ||
        investimento.perfil_risco ||
        investimento.perfilRisco ||
        ""
      ).trim().toLowerCase();

      return perfilInvestimento === perfilCliente;
    }
  );

  // 4. Retornar os dados de cada cliente
  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      investimentos: investimentosIndicados
    }
  };
});

return recomendacoes;

const clientes = $input.all();

return clientes.map(item => {
  const cliente = item.json;

  const investimentos = cliente.investimentos || [];

  const lista = investimentos.length > 0
    ? investimentos.map(investimento => {
        const nome = investimento.nome ||
                     investimento.investimento ||
                     investimento.produto ||
                     "Investimento";

        return `- ${nome}`;
      }).join("\n")
    : "Nenhum investimento compatível foi identificado.";

  const mensagem = `
Olá, ${cliente.nome}!

Preparamos uma análise inicial de investimentos para você.

Seu perfil: ${cliente.perfil}
Saldo informado: ${cliente.saldo}

Investimentos compatíveis com seu perfil:
${lista}

As sugestões são apenas informativas e não representam uma recomendação financeira individualizada.

Atenciosamente,
Assistente de Investimentos
`.trim();

  return {
    json: {
      ...cliente,
      mensagem
    }
  };
});

const resultados = $input.all();

return resultados.map(item => {
  const cliente = item.json;

  return {
    json: {
      cliente: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      quantidadeInvestimentos: (
        cliente.investimentos || []
      ).length,
      mensagem: cliente.mensagem,
      status: "MENSAGEM_GERADA"
    }
  };
});
